const canvas=host.querySelector('canvas'),ctx=canvas.getContext('2d');if(!ctx){mapNode.style.display='';host.remove();return}let yaw=70,pitch=35,zoom=1,down=false,lastX=0,lastY=0;const rad=Math.PI/180;
